import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"抽思","description":"","frontmatter":{"title":"抽思","date":"2026-11-24T00:00:00.000Z","seq":17,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"哀郢","link":"/blogs/楚辞/哀郢.html"},"next":{"text":"怀沙","link":"/blogs/楚辞/怀沙.html"}},"headers":[],"relativePath":"blogs/楚辞/抽思.md","filePath":"blogs/楚辞/抽思.md"}'),o={name:"blogs/楚辞/抽思.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="抽思" tabindex="-1">抽思 <a class="header-anchor" href="#抽思" aria-label="Permalink to &quot;抽思&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九章</p><div class="poem"><p class="poem-stanza">心郁郁之忧思兮，独永叹乎增伤。</p><p class="poem-stanza">思蹇产之不释兮，曼遭夜之方长。</p><p class="poem-stanza">悲秋风之动容兮，何回极之浮浮。</p><p class="poem-stanza">数惟荪之多怒兮，伤余心之忧忧。</p><p class="poem-stanza">愿摇起而横奔兮，览民尤以自镇。</p><p class="poem-stanza">结微情以陈词兮，矫以遗夫美人。</p><p class="poem-stanza">昔君与我诚言兮，曰黄昏以为期。</p><p class="poem-stanza">羌中道而回畔兮，反既有此他志。</p><p class="poem-stanza">憍吾以其美好兮，览余以其修姱。</p><p class="poem-stanza">与余言而不信兮，盖为余而造怒。</p><p class="poem-stanza">愿承閒而自察兮，心震悼而不敢。</p><p class="poem-stanza">悲夷犹而冀进兮，心怛伤之憺憺。</p><p class="poem-stanza">兹历情以陈辞兮，荪详聋而不闻。</p><p class="poem-stanza">固切人之不媚兮，众果以我为患。</p><p class="poem-stanza">初吾所陈之耿著兮，岂至今其庸亡？</p><p class="poem-stanza">何独乐斯之謇謇兮？</p><p class="poem-stanza">愿荪美之可光。</p><p class="poem-stanza">望三王以为像兮，指彭咸以为仪。</p><p class="poem-stanza">夫何极而不至兮，故远闻而难亏。</p><p class="poem-stanza">善不由外来兮，名不可以虚作。</p><p class="poem-stanza">孰无施而有报兮，孰不实而有获？</p><p class="poem-stanza">少歌曰：与美人抽思兮，并日夜而无正。</p><p class="poem-stanza">憍吾以其美好兮，敖朕辞而不听。</p><p class="poem-stanza">倡曰：</p><p class="poem-stanza">有鸟自南兮，来集汉北。</p><p class="poem-stanza">好姱佳丽兮，牉独处此异域。</p><p class="poem-stanza">惸茕独而不群兮，又无良媒在其侧。</p><p class="poem-stanza">道卓远而日忘兮，愿自申而不得。</p><p class="poem-stanza">望北山而流涕兮，临流水而太息。</p><p class="poem-stanza">望孟夏之短夜兮，何晦明之若岁？</p><p class="poem-stanza">惟郢路之辽远兮，魂一夕而九逝。</p><p class="poem-stanza">曾不知路之曲直兮，南指月与列星。</p><p class="poem-stanza">愿径逝而未得兮，魂识路之营营。</p><p class="poem-stanza">何灵魂之信直兮，人之心不与吾心同！</p><p class="poem-stanza">理弱而媒不通兮，尚不知余之从容。</p><p class="poem-stanza">乱曰：</p><p class="poem-stanza">长濑湍流，溯江潭兮。</p><p class="poem-stanza">狂顾南行，聊以娱心兮。</p><p class="poem-stanza">轸石崴嵬，蹇吾愿兮。</p><p class="poem-stanza">超回志度，行隐进兮。</p><p class="poem-stanza">低徊夷犹，宿北姑兮。</p><p class="poem-stanza">烦冤瞀容，实沛徂兮。</p><p class="poem-stanza">愁叹苦神，灵遥思兮。</p><p class="poem-stanza">路远处幽，又无行媒兮。</p><p class="poem-stanza">道思作颂，聊以自救兮。</p><p class="poem-stanza">忧心不遂，斯言谁告兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
